// Turn the single profile row into one search per title.
//
// `limit` is the profile's max_jobs_per_run — the rate-limit guard. It is
// clamped here as well as in the backend, because a bad value would be spent
// as real API quota before the backend ever saw it.

const profile = $input.first().json;

const titles = Array.isArray(profile.search_titles) && profile.search_titles.length > 0
  ? profile.search_titles
  : ['Flutter'];

const limit = Math.min(Math.max(Number(profile.max_jobs_per_run) || 10, 1), 100);

return titles
  .map((t) => String(t).trim())
  .filter((t) => t.length > 0)
  .map((query_title) => ({ json: { query_title, limit } }));

// Wrap this search's results into the backend's ingest envelope.
//
// Fetch jobs runs with neverError + fullResponse, so this ALWAYS receives
// exactly one item: { statusCode, headers, body }. Two bugs made that
// necessary, both found on live data:
//
// 1. The loop only advances when something flows back into it. While the
//    fetch node was allowed to emit nothing on an empty result, a search
//    returning zero jobs killed the chain and every LATER search term was
//    silently skipped - 'Dart Developer' returning 0 stopped the run dead
//    and 'Flutter' would have been skipped had it been listed second.
//
// 2. An HTTP failure and an empty result are different events. A 429
//    recorded as 'returned 0' is fetch_log lying about the one thing it
//    exists to report - API consumption.

const search = $('Loop over searches').first().json;
const resp = $input.first().json;

const status = resp.statusCode === undefined ? 200 : resp.statusCode;
const body = resp.body === undefined ? resp : resp.body;

let jobs = [];
let notes = `WF-A ${$execution.id}`;

if (status >= 400) {
  const msg = (body && (body.message || (body.error && body.error.message))) || `HTTP ${status}`;
  notes += ` | FETCH FAILED ${status}: ${String(msg).slice(0, 160)}`;
} else if (Array.isArray(body)) {
  jobs = body.filter((j) => j && j.id);
}

return [{ json: { query_title: search.query_title, notes, jobs } }];
